```java
import java.io.*;
import java.nio.file.*;

public class FileServer {
    public void serveFile(String filename) throws IOException {
        Path baseDirectory = Paths.get("/var/www/html/uploads/").toAbsolutePath().normalize();

        // Resolve the requested path and normalize it to remove "../" sequences
        Path targetPath = baseDirectory.resolve(filename).normalize();

        // Security Check: Ensure the resulting path still resides within the base directory
        if (!targetPath.startsWith(baseDirectory)) {
            throw new SecurityException("Access Denied: Invalid file path attempt.");
        }

        // Now it is safe to read the file
        byte[] content = Files.readAllBytes(targetPath);
        System.out.println(new String(content));
    }
}
```

